describe('Select All Rows with Header Checkbox', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should select all rows when header checkbox is clicked', () => {
    // Verify table header checkbox is visible
    cy.get('[data-testid="table-header-checkbox"]').should('be.visible');
    // Verify all rows are initially unselected
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('not.have.class', 'selected');
    });

    // Click the header checkbox to select all rows
    cy.get('[data-testid="table-header-checkbox"]').click();

    // Verify all rows now have the 'selected' class
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('have.class', 'selected');
    });

    // Verify selection status is reflected in UI
    cy.get('[data-testid="selected-count"]').should('contain', 'All rows selected');
  });

  it('should deselect all rows when header checkbox is unchecked', () => {
    // Verify all rows are initially selected
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('have.class', 'selected');
    });

    // Click the header checkbox to unselect all rows
    cy.get('[data-testid="table-header-checkbox"]').click();

    // Verify all rows are now unselected
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('not.have.class', 'selected');
    });

    // Verify selection status is updated in UI
    cy.get('[data-testid="selected-count"]').should('contain', '0 rows selected');
  });
});
